#!/usr/bin/env python3
"""Validate a finalized PRD Score absolute-mode report."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any

import score_report


EXPECTED_IDS = {
    "layer1": [f"C{number}" for number in range(1, 12)],
    "layer2": [f"M{number}" for number in range(1, 10)],
    "writing_layer": [f"W{number}" for number in range(1, 5)],
}
GATE_BOOLEAN_FIELDS = (
    "pass",
    "incumbent_replacement",
    "ecosystem_diagrams_present",
    "model_room_requested",
    "model_room_present",
    "commercial_value_over_1m",
    "pricing_decomposition_present",
)


def _normalize(value: str) -> str:
    return re.sub(r"\s+", " ", value).strip().lower()


def _non_empty(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _criterion_rows(
    rows: Any,
    expected_ids: list[str],
    context: str,
    errors: list[str],
    reference_norm: str | None,
) -> tuple[int, int]:
    if not isinstance(rows, list):
        errors.append(f"{context} must be an array")
        return 0, 0
    ids = [row.get("id") for row in rows if isinstance(row, dict)]
    if ids != expected_ids:
        if expected_ids:
            errors.append(
                f"{context} must appear exactly once in {'-'.join((expected_ids[0], expected_ids[-1]))} order; got {ids}"
            )
        else:
            errors.append(f"{context} must be empty; got {ids}")
    used_quotes = 0
    invalid_used_quotes = 0
    for index, row in enumerate(rows):
        path = f"{context}[{index}]"
        if not isinstance(row, dict):
            errors.append(f"{path} must be an object")
            continue
        score = row.get("score")
        if isinstance(score, bool) or not isinstance(score, int) or not 0 <= score <= 5:
            errors.append(f"{path}.score must be an integer from 0 through 5")
            continue
        if not _non_empty(row.get("anchor")) or not row["anchor"].strip().startswith(
            f"{score}:"
        ):
            errors.append(f"{path}.anchor must quote the matched {score}: anchor row")
        if score < 4 and not _non_empty(row.get("fix")):
            errors.append(f"{path}.fix is required for every score below 4")
        evidence = row.get("evidence")
        if not isinstance(evidence, list) or not evidence:
            errors.append(
                f"{path}.evidence must contain used or explicitly missing evidence"
            )
            continue
        for evidence_index, item in enumerate(evidence):
            evidence_path = f"{path}.evidence[{evidence_index}]"
            if not isinstance(item, dict):
                errors.append(f"{evidence_path} must be an object")
                continue
            if item.get("status") not in {"used", "missing"}:
                errors.append(f"{evidence_path}.status must be used or missing")
            for key in ("source", "quote"):
                if not _non_empty(item.get(key)):
                    errors.append(f"{evidence_path}.{key} must be non-empty")
            if item.get("status") == "used" and _non_empty(item.get("quote")):
                used_quotes += 1
                if reference_norm is None:
                    invalid_used_quotes += 1
                    errors.append(
                        f"{evidence_path}.quote cannot be verified without source material"
                    )
                elif _normalize(item["quote"]) not in reference_norm:
                    invalid_used_quotes += 1
                    errors.append(
                        f"{evidence_path}.quote was not found verbatim in the supplied sources"
                    )
    return used_quotes, invalid_used_quotes


def validate(
    report: Any,
    reference_text: str | None = None,
    prd_text: str | None = None,
) -> dict[str, Any]:
    errors: list[str] = []
    warnings: list[str] = []
    reference_norm = _normalize(reference_text) if reference_text else None
    if not isinstance(report, dict):
        return {
            "ok": False,
            "errors": ["report must be an object"],
            "warnings": warnings,
            "used_quotes_verified": False,
            "arithmetic_verified": False,
        }

    required_strings = {
        "instrument": "prd-score",
        "mode": "absolute",
        "rubric_version": score_report.RUBRIC_VERSION,
        "validation_status": score_report.VALIDATION_STATUS,
        "calculation_version": score_report.CALCULATION_VERSION,
    }
    for key, expected in required_strings.items():
        if report.get(key) != expected:
            errors.append(f"{key} must equal {expected!r}")

    gate = report.get("artifact_gate")
    if not isinstance(gate, dict):
        errors.append("artifact_gate must be an object")
        gate = {}
    for key in GATE_BOOLEAN_FIELDS:
        if not isinstance(gate.get(key), bool):
            errors.append(f"artifact_gate.{key} must be a boolean")
    if not _non_empty(gate.get("reason")):
        errors.append("artifact_gate.reason must be non-empty")
    if (
        gate.get("incumbent_replacement") is True
        and gate.get("ecosystem_diagrams_present") is not True
        and gate.get("pass") is True
    ):
        errors.append(
            "artifact_gate cannot pass an incumbent replacement without ecosystem diagrams"
        )

    used_quotes = 0
    invalid_used_quotes = 0
    if gate.get("pass") is False:
        for key in ("layer1", "layer2", "writing_layer"):
            if report.get(key) != []:
                errors.append(f"{key} must be empty when the artifact gate fails")
        layer3 = report.get("layer3")
        if not isinstance(layer3, dict) or layer3.get("scores") != []:
            errors.append("layer3.scores must be empty when the artifact gate fails")
        if report.get("totals") is not None:
            errors.append("totals must be null when the artifact gate fails")
    elif gate.get("pass") is True:
        for key, ids in EXPECTED_IDS.items():
            used, invalid = _criterion_rows(
                report.get(key), ids, key, errors, reference_norm
            )
            used_quotes += used
            invalid_used_quotes += invalid
        layer3 = report.get("layer3")
        if not isinstance(layer3, dict) or not isinstance(layer3.get("in_scope"), bool):
            errors.append("layer3 must include boolean in_scope")
        else:
            expected_layer3 = (
                [f"P{number}" for number in range(1, 4)] if layer3["in_scope"] else []
            )
            used, invalid = _criterion_rows(
                layer3.get("scores"),
                expected_layer3,
                "layer3.scores",
                errors,
                reference_norm,
            )
            used_quotes += used
            invalid_used_quotes += invalid
        if not _non_empty(report.get("anchor_placement")):
            errors.append(
                "anchor_placement must compare the result with portfolio anchors"
            )

    arithmetic_verified = False
    try:
        recalculated = score_report.finalize(
            report, prd_text if prd_text is not None else reference_text or ""
        )
        derived_keys = (
            "status",
            "length_normalization",
            "hard_caps",
            "integration_subscore",
            "totals",
            "lowest_three",
            "fix_plan_ranked",
            "calculation_version",
            "layer1",
            "layer2",
            "layer3",
            "writing_layer",
        )
        mismatches = [
            key for key in derived_keys if report.get(key) != recalculated.get(key)
        ]
        if mismatches:
            errors.append(
                "report does not match the deterministic calculation for "
                + ", ".join(mismatches)
            )
        else:
            arithmetic_verified = True
    except Exception as exc:
        errors.append(f"deterministic calculation could not be verified: {exc!r}")

    return {
        "ok": not errors,
        "errors": errors,
        "warnings": warnings,
        "used_quotes_verified": invalid_used_quotes == 0
        and (used_quotes == 0 or reference_norm is not None),
        "arithmetic_verified": arithmetic_verified,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("report", type=Path)
    parser.add_argument("--artifact", type=Path, required=True)
    parser.add_argument(
        "--source",
        type=Path,
        action="append",
        default=[],
        help=(
            "additional source material (for example the commercial proposal) "
            "used for verbatim-quote verification; repeatable. The PRD line "
            "count is always taken from --artifact alone."
        ),
    )
    args = parser.parse_args()
    report = json.loads(args.report.read_text(encoding="utf-8"))
    artifact = args.artifact.read_text(encoding="utf-8", errors="replace")
    sources = [
        path.read_text(encoding="utf-8", errors="replace") for path in args.source
    ]
    reference = "\n\n".join([artifact, *sources])
    result = validate(report, reference_text=reference, prd_text=artifact)
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 0 if result["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
